import type { GatewayClient } from '../gateway/client.js'
import { logger } from '../log.js'
import type { PaymentStore } from '../store/payments.js'

const LOCK_TTL_MS = 30_000

export async function settlePending(gateway: GatewayClient, store: PaymentStore): Promise<number> {
  const lock = await store.acquireLock('settlement', LOCK_TTL_MS)
  if (!lock) return 0
  let settled = 0
  try {
    const pending = await store.listAuthorized({ limit: 500 })
    for (const payment of pending) {
      const result = await gateway.capture({ paymentId: payment.id, amountMinor: payment.amountMinor })
      if (!result.ok) {
        logger.warn({ paymentId: payment.id, code: result.error.code }, 'capture failed')
        continue
      }
      await store.markCaptured(payment.id, result.capturedAt)
      settled += 1
    }
  } finally {
    await lock.release()
  }
  return settled
}

