import { describe, expect, test } from 'bun:test'

import type { CaptureResult, GatewayClient } from '../../src/gateway/client.js'
import { captureWithRetry } from '../../src/settlement/retry.js'

const FAST = { maxAttempts: 3, baseDelayMs: 1, maxDelayMs: 2 }
const timeout: CaptureResult = { ok: false, error: { code: 'gateway_timeout', message: 'upstream timed out' } }
const ok: CaptureResult = { ok: true, capturedAt: '2026-11-10T09:00:00.000Z' }

function scripted(results: CaptureResult[]): GatewayClient & { calls: number } {
  const client = {
    calls: 0,
    async capture() {
      return results[Math.min(client.calls++, results.length - 1)]!
    },
  }
  return client
}

describe('captureWithRetry', () => {
  test('returns the first successful capture', async () => {
    const gateway = scripted([timeout, ok])
    expect(await captureWithRetry(gateway, 'pay_1', 1200, FAST)).toEqual(ok)
    expect(gateway.calls).toBe(2)
  })

  test('gives up after maxAttempts', async () => {
    const gateway = scripted([timeout])
    const result = await captureWithRetry(gateway, 'pay_2', 1200, FAST)
    expect(result.ok).toBe(false)
    expect(gateway.calls).toBe(3)
  })
})
